import{c as t,Q as n,j as s,m as e}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"Async","description":"","frontmatter":{},"headers":[{"level":1,"title":"Async","slug":"async"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/工具函数/Async.md","filePath":"api/SIMD-API/基础API/工具函数/Async.md"}'),l={name:"api/SIMD-API/基础API/工具函数/Async.md"};function p(i,a,r,d,c,o){return n(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="async" tabindex="-1">Async <a class="header-anchor" href="#async" aria-label="Permalink to &quot;Async&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>Async提供了一个统一的接口，用于在不同模式下（AIC或AIV）执行特定函数，从而避免代码中直接的硬件条件判断（如使用ASCEND_IS_AIV或ASCEND_IS_AIC）。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;EngineType engine, auto funPtr, class... Args&gt;</span></span>
<span class="line"><span>__aicore__ void Async(Args... args)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>engine</td><td>引擎模式，参数取值分别为AIC、AIV。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen1431192522519&quot;&gt;enum class EngineType : int32_t { AIC = 1, // 仅AIC AIV = 2 // 仅AIV };&lt;/pre&gt;</td></tr><tr><td>funPtr</td><td>函数指针，指定要执行的函数，函数签名和参数类型由class... Args决定。</td></tr><tr><td>class... Args</td><td>可变参数模板，表示函数参数的类型列表，用于传递给funPtr。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>Args... args</td><td>输入</td><td>与class... Args对应的参数列表，表示传递给funPtr的实际参数。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extern &quot;C&quot; __global__ __aicore__ void baremix_custom(GM_ADDR a, GM_ADDR b, GM_ADDR bias, GM_ADDR c,</span></span>
<span class="line"><span>                                                              GM_ADDR workspace, GM_ADDR tilingGm)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);</span></span>
<span class="line"><span>    AscendC::TPipe pipe;</span></span>
<span class="line"><span>    TCubeTiling tiling;</span></span>
<span class="line"><span>    CopyTiling(&amp;tiling, tilingGm);</span></span>
<span class="line"><span>    // 避免代码中直接的硬件条件判断（如使用ASCEND_IS_AIV或ASCEND_IS_AIC）</span></span>
<span class="line"><span>    Async&lt;EngineType::AIC, aicOperation&gt;(a, b, bias, c, workspace, tiling, &amp;pipe);</span></span>
<span class="line"><span>    Async&lt;EngineType::AIV, aivOperation&gt;(c, tiling, &amp;pipe);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>__aicore__ inline void aicOperation(GM_ADDR a, GM_ADDR b, GM_ADDR bias, GM_ADDR c, GM_ADDR workspace, const TCubeTiling &amp;tiling, AscendC::TPipe *pipe) {</span></span>
<span class="line"><span>    MatmulLeakyKernel&lt;half, half, float, float&gt; matmulLeakyKernel;</span></span>
<span class="line"><span>    matmulLeakyKernel.Init(a, b, bias, c, workspace, tiling, pipe);</span></span>
<span class="line"><span>    REGIST_MATMUL_OBJ(pipe, GetSysWorkSpacePtr(), matmulLeakyKernel.matmulObj, &amp;matmulLeakyKernel.tiling);</span></span>
<span class="line"><span>    matmulLeakyKernel.Process(pipe);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__aicore__ inline void aivOperation(GM_ADDR c, const TCubeTiling &amp;tiling, AscendC::TPipe *pipe) {</span></span>
<span class="line"><span>    LeakyReluKernel&lt;float&gt; leakyReluKernel;</span></span>
<span class="line"><span>    leakyReluKernel.Init(c, tiling, pipe);</span></span>
<span class="line"><span>    leakyReluKernel.Process(pipe);</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,18)])])}const _=t(l,[["render",p]]);export{h as __pageData,_ as default};
